const MARGONEURO_LEVEL_BLOCKED_EDGES_STORAGE_KEY = 'margoneuro_level_blocked_edges_v1';

function getHeroLevelValue() {
    const candidates = [
        typeof Engine !== 'undefined' ? Engine?.hero?.d?.lvl : null,
        typeof Engine !== 'undefined' ? Engine?.hero?.d?.level : null,
        typeof Engine !== 'undefined' ? Engine?.hero?.lvl : null,
        typeof Engine !== 'undefined' ? Engine?.hero?.level : null
    ];
    for (const value of candidates) {
        const lvl = parseInt(value, 10);
        if (Number.isFinite(lvl) && lvl > 0) return lvl;
    }
    const titleText = (typeof document !== 'undefined' && document?.title) ? document.title : '';
    const titleMatch = String(titleText || '').match(/\((\d+)\s*p\)/i);
    return titleMatch ? parseInt(titleMatch[1], 10) : 0;
}
window.getHeroLevelValue = getHeroLevelValue;

function normalizeGatewayLevelText(text) {
    return String(text || '')
        .replace(/<br\s*\/?>/gi, ' ')
        .replace(/<[^>]*>?/gm, ' ')
        .replace(/\u00A0/g, ' ')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
}

function parseGatewayLevelRequirementText(text) {
    const normalized = normalizeGatewayLevelText(text);
    if (!normalized || !/(przejsc|wejsc|portal|lokacj|bram)/.test(normalized) || !/(poziom|level|lvl|gracz)/.test(normalized)) {
        return null;
    }
    const patterns = [
        /(?:dla\s+gracz\w*\s+)?od\s+(\d{1,3})\s*(?:poziom|lvl|level)/i,
        /(?:wymagan\w*|minimum|min\.?)\s*(?:poziom|lvl|level)?\s*(\d{1,3})/i,
        /(?:poziom|lvl|level)\s*(?:od|minimum|min\.?|wymagan\w*)?\s*(\d{1,3})/i
    ];
    for (const pattern of patterns) {
        const match = normalized.match(pattern);
        if (!match) continue;
        const minLevel = parseInt(match[1], 10);
        if (Number.isFinite(minLevel) && minLevel > 0) return minLevel;
    }
    return null;
}
window.parseGatewayLevelRequirementText = parseGatewayLevelRequirementText;

function getLevelBlockedEdgeKey(from, to) {
    const fromKey = normMapName(from);
    const toKey = normMapName(to);
    return fromKey && toKey ? `${fromKey}->${toKey}` : '';
}

function getLevelBlockedEdgesStore() {
    if (!window.__margoneuroLevelBlockedEdges || typeof window.__margoneuroLevelBlockedEdges !== 'object') {
        const raw = (() => {
            try { return margoneuroReadStorage(MARGONEURO_LEVEL_BLOCKED_EDGES_STORAGE_KEY) || localStorage.getItem(MARGONEURO_LEVEL_BLOCKED_EDGES_STORAGE_KEY); } catch (e) { return ''; }
        })();
        window.__margoneuroLevelBlockedEdges = safeJsonParse(raw, {}) || {};
    }
    return window.__margoneuroLevelBlockedEdges;
}

function saveLevelBlockedEdgesStore() {
    try {
        margoneuroWriteStorage(MARGONEURO_LEVEL_BLOCKED_EDGES_STORAGE_KEY, JSON.stringify(window.__margoneuroLevelBlockedEdges || {}));
    } catch (e) {}
}

function removeLevelBlockedEdge(from, to, reason = 'level_ok') {
    const key = getLevelBlockedEdgeKey(from, to);
    const store = getLevelBlockedEdgesStore();
    if (!key || !store[key]) return false;
    delete store[key];
    saveLevelBlockedEdgesStore();
    window.__routePathCacheVersion = (window.__routePathCacheVersion || 0) + 1;
    window.__internalMapGraphCache = null;
    window.__fastRouteIndexCache = null;
    logEvent('GATE-LEVEL', `${from} -> ${to} odblokowane (${reason})`, 60000, '#81c784', { key: `gate_level_unblock:${key}`, verboseOnly: true });
    return true;
}

function getLevelBlockedEdgeRecord(from, to) {
    const key = getLevelBlockedEdgeKey(from, to);
    return key ? getLevelBlockedEdgesStore()[key] || null : null;
}

function isGatewayLevelBlockedForHero(from, to, options = {}) {
    if (options?.ignoreLevelRequirements) return false;
    const rec = getLevelBlockedEdgeRecord(from, to);
    if (!rec) return false;
    const minLevel = parseInt(rec.minLevel || rec.requiredLevel || 0, 10);
    if (!Number.isFinite(minLevel) || minLevel <= 0) return false;
    const heroLevel = getHeroLevelValue();
    if (heroLevel > 0 && heroLevel >= minLevel) {
        removeLevelBlockedEdge(from, to, `hero_lvl_${heroLevel}`);
        return false;
    }
    return true;
}
window.isGatewayLevelBlockedForHero = isGatewayLevelBlockedForHero;

function markGatewayAsLevelBlocked(from, to, minLevel, reason = 'level_requirement') {
    if (!from || !to) return false;
    minLevel = parseInt(minLevel, 10);
    if (!Number.isFinite(minLevel) || minLevel <= 0) return false;
    const key = getLevelBlockedEdgeKey(from, to);
    if (!key) return false;
    const now = Date.now();
    const store = getLevelBlockedEdgesStore();
    const prev = store[key] || {};
    store[key] = {
        fromMap: from,
        toMap: to,
        fromKey: normMapName(from),
        toKey: normMapName(to),
        minLevel: Math.max(minLevel, Number(prev.minLevel || 0)),
        heroLevelAtBlock: getHeroLevelValue(),
        reason,
        updatedAt: now,
        firstSeenAt: prev.firstSeenAt || now
    };
    saveLevelBlockedEdgesStore();

    const sourceKey = Object.keys(globalGateways || {}).find(k => normMapName(k) === normMapName(from));
    const targetKey = sourceKey ? Object.keys(globalGateways[sourceKey] || {}).find(k => normMapName(k) === normMapName(to)) : null;
    if (sourceKey && targetKey && globalGateways[sourceKey][targetKey]) {
        globalGateways[sourceKey][targetKey] = {
            ...globalGateways[sourceKey][targetKey],
            minLevel: store[key].minLevel,
            levelRequirement: store[key].minLevel,
            levelBlockedAt: now,
            temporaryFailReason: reason
        };
        try { saveGateways(); } catch (e) {}
    }

    window.__routePathCacheVersion = (window.__routePathCacheVersion || 0) + 1;
    window.__internalMapGraphCache = null;
    window.__fastRouteIndexCache = null;
    if (window.__routePathCache instanceof Map) window.__routePathCache.clear();
    if (normMapName(window.rushNextMap || '') === normMapName(to)) {
        window.rushNextMap = null;
        window.rushFullPath = null;
        window._lastRushNextMap = null;
    }
    if (typeof releaseExpGatewayTransition === 'function') {
        releaseExpGatewayTransition('level_requirement', { cooldown: true });
    } else {
        window.__pendingGatewayTransition = null;
    }
    const msg = `Przejscie [${from}] -> [${to}] wymaga poziomu ${store[key].minLevel}, wybieram objazd.`;
    logEvent('GATE-LEVEL', msg, 10000, '#ffb74d', { key: `gate_level_block:${key}` });
    return true;
}
window.markGatewayAsLevelBlocked = markGatewayAsLevelBlocked;

function closeGatewayLevelRequirementDialog() {
    try {
        const roots = Array.from(document.querySelectorAll('.margo-window, .c-window, .alert-window, .dialog-window, [role="dialog"], .message-window, .message, .window')).slice(0, 30);
        for (const root of roots) {
            const text = root?.innerText || root?.textContent || '';
            if (!parseGatewayLevelRequirementText(text)) continue;
            const btn = Array.from(root.querySelectorAll('button, .button, .btn, a, div, span'))
                .find(el => /^(ok|okej|\[?e\]?|zamknij)$/i.test(String(el?.textContent || '').replace(/\s+/g, ' ').trim()) && el.offsetParent !== null);
            if (btn && typeof btn.click === 'function') {
                btn.click();
                return true;
            }
        }
    } catch (e) {}
    return false;
}

function detectGatewayLevelRequirementModal(source = 'poll') {
    const now = Date.now();
    if (now - Number(window.__lastGatewayLevelRequirementScanAt || 0) < 650) return false;
    const pending = window.__pendingGatewayTransition || null;
    const fromMap = pending?.fromMap || (typeof getCurrentMapName === 'function' ? getCurrentMapName() : '');
    const toMap = pending?.toMap || window.rushNextMap || '';
    if (!fromMap || !toMap || (!pending && !window.isRushing && !window.isExping && !(typeof isPatrolling !== 'undefined' && isPatrolling))) return false;
    window.__lastGatewayLevelRequirementScanAt = now;

    let text = '';
    try {
        const roots = Array.from(document.querySelectorAll('.margo-window, .c-window, .alert-window, .dialog-window, [role="dialog"], .message-window, .message, .window')).slice(0, 30);
        text = roots.map(el => String(el?.innerText || el?.textContent || '').slice(0, 800)).filter(Boolean).join('\n');
        if (!parseGatewayLevelRequirementText(text)) {
            text = String(document?.body?.innerText || '').slice(-12000);
        }
    } catch (e) {
        text = '';
    }
    const minLevel = parseGatewayLevelRequirementText(text);
    if (!minLevel) return false;
    const marked = markGatewayAsLevelBlocked(fromMap, toMap, minLevel, source);
    closeGatewayLevelRequirementDialog();
    if (marked && typeof scheduleRushStep === 'function') scheduleRushStep(350, 'gateway_level_block_replan');
    return marked;
}
window.detectGatewayLevelRequirementModal = detectGatewayLevelRequirementModal;

function deleteRuntimeEdgeBan(store, from, to) {
    if (!store || !from || !to) return 0;
    let removed = 0;
    const fromNorm = normMapName(from);
    const toNorm = normMapName(to);
    for (const fromKey of Object.keys(store)) {
        if (normMapName(fromKey) !== fromNorm || !store[fromKey] || typeof store[fromKey] !== 'object') continue;
        for (const toKey of Object.keys(store[fromKey])) {
            if (normMapName(toKey) !== toNorm) continue;
            delete store[fromKey][toKey];
            removed++;
        }
        if (Object.keys(store[fromKey]).length === 0) delete store[fromKey];
    }
    return removed;
}

function clearGatewayRuntimeBlocks(from, to, reason = 'reachable_again') {
    if (!from || !to) return 0;
    cleanupExpiredEdgeBans();
    let removed = 0;
    removed += deleteRuntimeEdgeBan(window.__bannedEdges, from, to);
    removed += deleteRuntimeEdgeBan(window.__physicalBlockedEdges, from, to);
    if (typeof unblockStaticEdgesBetweenMaps === 'function') removed += unblockStaticEdgesBetweenMaps(from, to, reason);
    if (typeof clearExpGatewayBlocked === 'function') removed += clearExpGatewayBlocked(from, to, reason) ? 1 : 0;

    const sourceKey = Object.keys(globalGateways || {}).find(k => normMapName(k) === normMapName(from));
    const targetKey = sourceKey ? Object.keys(globalGateways[sourceKey] || {}).find(k => normMapName(k) === normMapName(to)) : null;
    if (sourceKey && targetKey && globalGateways[sourceKey][targetKey]) {
        const entry = globalGateways[sourceKey][targetKey];
        if (entry.status === 'temporary_failed' || entry.status === 'suspected') {
            globalGateways[sourceKey][targetKey] = {
                ...entry,
                status: Number(entry.successCount || 0) > 0 || Number(entry.lastUsedAt || entry.confirmedAt || 0) > 0 ? 'confirmed' : 'available',
                blockedUntil: 0,
                temporaryFailReason: '',
                lastSeenAt: Date.now()
            };
            try { saveGateways(); } catch (e) {}
            removed++;
        }
    }

    if (removed > 0) {
        window.__routePathCacheVersion = (window.__routePathCacheVersion || 0) + 1;
        window.__internalMapGraphCache = null;
        logEvent('GATE-UNBLOCK', `${from} -> ${to} reason=${reason}`, 60000, '#81c784', { key: `gate_unblock:${normMapName(from)}:${normMapName(to)}`, verboseOnly: true });
    }
    return removed;
}
window.clearGatewayRuntimeBlocks = clearGatewayRuntimeBlocks;

function findReachableGatewayCandidateForBlockCheck(currentSysMap, nextMap, distMap = null) {
    if (!currentSysMap || !nextMap) return null;
    const map = distMap || (typeof buildDistanceMapFromHero === 'function' ? buildDistanceMapFromHero() : null);
    const nextNorm = normMapName(nextMap);

    const liveDoor = (typeof getCurrentMapGatewaysForRadar === 'function' ? getCurrentMapGatewaysForRadar(map) : [])
        .filter(g => g?.reachable && normMapName(g.targetMap || '') === nextNorm)
        .sort((a, b) => (a.pathDistance || 9999) - (b.pathDistance || 9999))[0];
    if (liveDoor) return { ...liveDoor, source: 'live-engine-gateway' };

    const sourceKey = Object.keys(globalGateways || {}).find(k => normMapName(k) === normMapName(currentSysMap));
    const targetKey = sourceKey ? Object.keys(globalGateways[sourceKey] || {}).find(k => normMapName(k) === nextNorm) : null;
    const baseDoor = sourceKey && targetKey ? globalGateways[sourceKey][targetKey] : null;
    const memoryDoor = baseDoor && typeof pickBestReachableGatewayCoordFromBaseDoor === 'function'
        ? pickBestReachableGatewayCoordFromBaseDoor(baseDoor, map, currentSysMap, nextMap)
        : null;
    if (memoryDoor) return { ...memoryDoor, targetMap: nextMap, source: 'transition-memory' };

    const staticDoor = typeof pickStaticGatewayCandidateForNextHop === 'function'
        ? pickStaticGatewayCandidateForNextHop(currentSysMap, nextMap, map, { includeBlocked: true, reachRadius: 3, unblockIfReachable: false })
        : null;
    if (staticDoor) return staticDoor;

    return null;
}

function invalidateActiveRushPathForBlockedEdge(currentSysMap, nextMap, reason = 'gateway_blocked') {
    const fromKey = normMapName(currentSysMap);
    const nextKey = normMapName(nextMap);
    if (!fromKey || !nextKey) return false;

    const fullPath = Array.isArray(window.rushFullPath) ? window.rushFullPath : [];
    const pathIdx = fullPath.findIndex(mapName => normMapName(mapName) === fromKey);
    const pathUsesEdge = pathIdx >= 0 && pathIdx < fullPath.length - 1 && normMapName(fullPath[pathIdx + 1]) === nextKey;
    const nextMatches = !!(window.rushNextMap && normMapName(window.rushNextMap) === nextKey);
    if (!pathUsesEdge && !nextMatches) return false;

    window.rushNextMap = null;
    window._lastRushNextMap = null;
    window.rushFullPath = [];
    window.__rushNoPathRecovery = null;
    window.__rushGatewayDoorCache = null;
    window.__expRuntimeRoutePlanCache = {};
    window.__expChooseNextMapCache = null;
    window.__routePathCacheVersion = (window.__routePathCacheVersion || 0) + 1;

    if (window.isExping) {
        if (typeof releaseExpGatewayTransition === 'function') {
            releaseExpGatewayTransition(reason, { cooldown: true });
        }
        try { expLastActionTime = 0; } catch (e) {}
        window.__lastExpLogicRunAt = 0;
        window.__nextExpLogicAllowedAt = 0;
        if (typeof window.requestExpLogicSoon === 'function') window.requestExpLogicSoon(250, reason);
    }

    const activeRush = !!(window.isRushing || (typeof isRushing !== 'undefined' && isRushing));
    if (activeRush && window.rushTarget && normMapName(window.rushTarget) !== fromKey && typeof scheduleRushStep === 'function') {
        scheduleRushStep(350, reason);
    }
    return true;
}
window.invalidateActiveRushPathForBlockedEdge = invalidateActiveRushPathForBlockedEdge;

function markGatewayAsBlocked(currentSysMap, nextMap, duration, reason = 'temporary') {
    cleanupExpiredEdgeBans();
    const expModeActive = !!window.isExping;
    const shopRushActive = !!window.isRushingToShop || !!window.autoSellState?.active || !!window.autoPotState?.active;
    const patrolOrManualRushActive = !!(
        (typeof isPatrolling !== 'undefined' && isPatrolling) ||
        window.isPatrolling ||
        (typeof isRushing !== 'undefined' && isRushing) ||
        window.isRushing
    );
    if (!expModeActive && !shopRushActive && patrolOrManualRushActive) {
        logEvent(
            'GATE-BLOCK-SUPPRESS',
            `${currentSysMap} -> ${nextMap} reason=${reason} skipped for hero/manual rush`,
            30000,
            '#90caf9',
            { key: `gate_block_skip_non_exp:${normMapName(currentSysMap)}:${normMapName(nextMap)}:${reason}`, verboseOnly: true }
        );
        return false;
    }
    const physicalLike = reason === 'physical' || reason === 'unreachable' || reason === 'stuck';
    const reachableCandidate = physicalLike ? findReachableGatewayCandidateForBlockCheck(currentSysMap, nextMap) : null;
    if (reachableCandidate && reason === 'unreachable') {
        clearGatewayRuntimeBlocks(currentSysMap, nextMap, `reachable_${reachableCandidate.source || 'gateway'}`);
        logEvent('GATE-BLOCK-SUPPRESS', `${currentSysMap} -> ${nextMap} reachable via ${reachableCandidate.source || 'gateway'}, skip unreachable block`, 60000, '#81c784', { key: `gate_block_suppress:${normMapName(currentSysMap)}:${normMapName(nextMap)}`, verboseOnly: true });
        return false;
    }

    banEdge(currentSysMap, nextMap, duration || 30000);
    if (physicalLike && !reachableCandidate) {
        banPhysicalEdge(currentSysMap, nextMap, Math.max(duration || 0, 90000));
    }
    if (typeof markExpGatewayBlocked === 'function' && !reachableCandidate) {
        markExpGatewayBlocked(currentSysMap, nextMap, duration || 30000, reason);
    }
    const sourceKey = Object.keys(globalGateways || {}).find(k => normMapName(k) === normMapName(currentSysMap));
    const targetKey = sourceKey ? Object.keys(globalGateways[sourceKey] || {}).find(k => normMapName(k) === normMapName(nextMap)) : null;
    if (!reachableCandidate && sourceKey && targetKey && globalGateways[sourceKey][targetKey]) {
        const entry = globalGateways[sourceKey][targetKey];
        globalGateways[sourceKey][targetKey] = {
            ...entry,
            status: isGatewayEntryProtected(entry) ? getGatewayEntryStatus(entry) : 'temporary_failed',
            failCount: Number(entry.failCount || 0) + 1,
            blockedUntil: Date.now() + (duration || 30000),
            temporaryFailReason: reason,
            lastSeenAt: entry.lastSeenAt || Date.now()
        };
        saveGateways();
    }
    if (typeof blockStaticEdgesBetweenMaps === 'function' && !reachableCandidate) {
        blockStaticEdgesBetweenMaps(currentSysMap, nextMap, Math.max(duration || 0, 10 * 60 * 1000), reason);
    } else if (reachableCandidate) {
        clearGatewayRuntimeBlocks(currentSysMap, nextMap, `reachable_${reachableCandidate.source || 'gateway'}`);
    }
    if (!reachableCandidate && typeof invalidateActiveRushPathForBlockedEdge === 'function') {
        invalidateActiveRushPathForBlockedEdge(currentSysMap, nextMap, `gateway_blocked:${reason}`);
    }
    return true;
}

function pickDoorToNextHop(currentSysMap, nextHop, distMap, reachableDoors) {
    if (!currentSysMap || !nextHop) return null;

    const normalizedNextHop = normMapName(nextHop);
    let door = (reachableDoors || []).find(g => normMapName(g.targetMap || '') === normalizedNextHop) || null;
    if (door) return door;

    const baseDoor = (typeof globalGateways !== 'undefined' && globalGateways?.[currentSysMap]?.[nextHop])
        ? globalGateways[currentSysMap][nextHop]
        : null;
    if (baseDoor) {
        const bestBaseCoord = typeof pickBestReachableGatewayCoordFromBaseDoor === 'function'
            ? pickBestReachableGatewayCoordFromBaseDoor(baseDoor, distMap, currentSysMap, nextHop)
            : null;
        if (bestBaseCoord) {
            return {
                x: bestBaseCoord.x,
                y: bestBaseCoord.y,
                targetMap: nextHop,
                pathDistance: bestBaseCoord.pathDistance,
                source: 'memory'
            };
        }
    }

    const staticDoor = typeof pickStaticGatewayCandidateForNextHop === 'function'
        ? pickStaticGatewayCandidateForNextHop(currentSysMap, nextHop, distMap)
        : null;
    return staticDoor || null;
}

function getActiveRouteContextMaps() {
    if (Array.isArray(window.rushFullPath) && window.rushFullPath.length > 0) {
        return window.rushFullPath.filter(Boolean);
    }
    if (window.isExping) {
        if (typeof getCurrentExpHuntMaps === 'function') {
            const maps = getCurrentExpHuntMaps();
            if (Array.isArray(maps) && maps.length > 0) return maps.filter(Boolean);
        }
        if (botSettings?.exp && Array.isArray(botSettings.exp.mapOrder)) {
            return botSettings.exp.mapOrder.filter(Boolean);
        }
    }
    const patrolWillResume = !!(typeof window.resumePatrolAfterRush !== 'undefined' && window.resumePatrolAfterRush);
    if (typeof isPatrolling !== 'undefined' && (isPatrolling || patrolWillResume)) {
        const hero = document.getElementById('selHero') ? document.getElementById('selHero').value : null;
        if (hero && heroMapOrder && Array.isArray(heroMapOrder[hero]) && heroMapOrder[hero].length > 0) {
            return heroMapOrder[hero].filter(Boolean);
        }
    }
    return [];
}

function pickNextReachableMapFromRoute(currentSysMap, allowedMaps) {
    let hero = document.getElementById('selHero') ? document.getElementById('selHero').value : null;
    let mapList = Array.isArray(allowedMaps) && allowedMaps.length ? [...allowedMaps] : [];
    if (!mapList.length && typeof getActiveRouteContextMaps === 'function') {
        mapList = getActiveRouteContextMaps();
    }
    if (!mapList.length) {
        mapList = (typeof botSettings !== 'undefined' && botSettings.exp) ? botSettings.exp.mapOrder : [];
    }
    if ((!mapList || mapList.length === 0) && typeof heroMapOrder !== 'undefined') { if (hero && heroMapOrder[hero]) mapList = heroMapOrder[hero]; }
    if (!mapList || mapList.length === 0) return null;

    const distMap = typeof buildDistanceMapFromHero === 'function' ? buildDistanceMapFromHero() : new Map();
    const reachableDoors = getCurrentMapGatewaysForRadar(distMap).filter(g => g.reachable && g?.targetMap);
    const currNorm = normMapName(currentSysMap);
    const currIdx = mapList.findIndex(m => normMapName(m) === currNorm);
    const orderedMaps = currIdx === -1
        ? mapList
        : mapList.map((_, offset) => mapList[(currIdx + offset + 1) % mapList.length]);

    for (const checkMap of orderedMaps) {
        if (!checkMap || normMapName(checkMap) === currNorm) continue;
        if (window.__bannedMaps && window.__bannedMaps[checkMap] && Date.now() < window.__bannedMaps[checkMap]) continue;

        const path = typeof getShortestPath === 'function' ? getShortestPath(currentSysMap, checkMap, routePathOptions()) : null;
        if (!path || path.length < 2) continue;

        const nextHop = path[1];
        const door = pickDoorToNextHop(currentSysMap, nextHop, distMap, reachableDoors);
        if (!door) continue;

        return { nextMap: checkMap, nextHop, door, path };
    }
    return null;
}

function pickSmartTransitGateway(currentSysMap, preferredTargets) {
    if (!currentSysMap) return null;
    const targets = Array.isArray(preferredTargets) ? preferredTargets.filter(Boolean) : [];
    if (!targets.length) return null;

    const distMap = typeof buildDistanceMapFromHero === 'function' ? buildDistanceMapFromHero() : new Map();
    const reachableDoors = getCurrentMapGatewaysForRadar(distMap).filter(g => g.reachable && g?.targetMap);
    if (!reachableDoors.length) return null;

    const currNorm = normMapName(currentSysMap);
    const normalizedTargets = targets.map(t => normMapName(t));
    let best = null;

    for (const door of reachableDoors) {
        const viaMap = (door.targetMap || '').trim();
        if (!viaMap || normMapName(viaMap) === currNorm) continue;
        if (isEdgeBanned(currentSysMap, viaMap)) continue;

        const viaNorm = normMapName(viaMap);
        let bestDoorScore = Infinity;
        let bestDoorTarget = null;
        let bestDoorPath = null;

        for (let i = 0; i < targets.length; i++) {
            const finalTarget = targets[i];
            if (!finalTarget) continue;
            const targetNorm = normalizedTargets[i];
            if (!targetNorm || targetNorm === viaNorm) {
                if (0 < bestDoorScore) {
                    bestDoorScore = 0;
                    bestDoorTarget = finalTarget;
                    bestDoorPath = [viaMap, finalTarget];
                }
                continue;
            }
            const p = typeof getShortestPath === 'function'
                ? getShortestPath(viaMap, finalTarget, routePathOptions())
                : null;
            if (!p || p.length < 2) continue;
            const score = p.length - 1;
            if (score < bestDoorScore) {
                bestDoorScore = score;
                bestDoorTarget = finalTarget;
                bestDoorPath = p;
            }
        }

        if (!Number.isFinite(bestDoorScore)) continue;
        if (!best || bestDoorScore < best.score || (bestDoorScore === best.score && door.pathDistance < best.door.pathDistance)) {
            best = {
                nextMap: viaMap,
                finalTarget: bestDoorTarget,
                path: bestDoorPath,
                door,
                score: bestDoorScore
            };
        }
    }

    return best;
}

function getExpGroupNameForMap(mapName) {
    if (!mapName) return null;
    let source = (typeof botSettings !== 'undefined' && Array.isArray(botSettings.expProfiles) && botSettings.expProfiles.length > 0)
        ? botSettings.expProfiles
        : (Array.isArray(window.defaultExpProfiles) ? window.defaultExpProfiles : []);
    let mapLower = mapName.toLowerCase();
    let profile = source.find(p => Array.isArray(p.maps) && p.maps.some(m => (m || "").toLowerCase() === mapLower));
    return profile ? profile.name : null;
}

function isMapKnownInGatewayBase(mapName) {
    const key = normMapName(mapName);
    if (typeof isMapKnownInStaticKnowledge === 'function' && isMapKnownInStaticKnowledge(key)) return true;
    if (typeof globalGateways === 'undefined' || !globalGateways) return false;
    for (let source in globalGateways) {
        if (normMapName(source) === key) return true;
        for (const target of Object.keys(globalGateways[source] || {})) {
            if (normMapName(target) === key) return true;
        }
    }
    return false;
}
