   function initializeMargoneuro() {
        if (margoneuroInitialized) {
            console.log('[Boot] Margoneuro już zainicjalizowane, pomijam drugi start');
            return;
        }

        margoneuroBootReady = true;
        margoneuroInitialized = true;
        loadData();
        cleanOldGateways();
        initGUI();
        const guardedAutoDetectEngineData = () => {
            const busy = typeof isGameBusyOrLoading === 'function' ? isGameBusyOrLoading({ source: 'engine_auto_detect' }) : { busy: false };
            if (busy.busy) return;
            autoDetectEngineData();
        };
        setInterval(guardedAutoDetectEngineData, 2200);
        setInterval(heroPositionTracker, 350);
        setInterval(radarLoop, 900);
        setInterval(() => {
            const expContainer = document.getElementById('expContainer');
            const list = document.getElementById('expMapList');
            if (!expContainer || !list || expContainer.style.display === 'none') return;
            const busy = typeof isGameBusyOrLoading === 'function' ? isGameBusyOrLoading({ source: 'exp_map_list_render' }) : { busy: false };
            if (busy.busy) return;
            const now = Date.now();
            const minRenderMs = window.isExping ? 6000 : 1200;
            if (window.__lastExpMapListRenderAt && now - Number(window.__lastExpMapListRenderAt || 0) < minRenderMs) return;
            window.__lastExpMapListRenderAt = now;
            if (typeof window.renderExpMaps === 'function') window.renderExpMaps();
        }, 1000);
        startLocalBridgeClient();
        document.addEventListener('keydown', handleGlobalKeydown);
        setupMapClickListener();

        // --- AUTO-WZNAWIANIE BOTA PO REFRESHU (F5 / RELOAD) ---
        window.addEventListener('beforeunload', () => {
            // Zapisujemy, czy bot był włączony tuż przed zniknięciem strony
            if (window.isExping) {
                sessionStorage.setItem('hero_resume_exp', 'true');
                const resumeTarget = typeof getExpResumeTargetMap === 'function' ? getExpResumeTargetMap('beforeunload') : null;
                if (resumeTarget) sessionStorage.setItem('hero_resume_exp_target_map', resumeTarget);
            }
            else {
                sessionStorage.removeItem('hero_resume_exp');
                sessionStorage.removeItem('hero_resume_exp_target_map');
            }

            if (typeof isPatrolling !== 'undefined' && isPatrolling) sessionStorage.setItem('hero_resume_patrol', 'true');
            else sessionStorage.removeItem('hero_resume_patrol');
        });

        const resumeBotWhenStable = (mode, attempt = 0) => {
            const busy = typeof isGameBusyOrLoading === 'function' ? isGameBusyOrLoading({ source: `legacy_resume_${mode}` }) : { busy: false };
            if (busy.busy && attempt < 12) {
                setTimeout(() => resumeBotWhenStable(mode, attempt + 1), /engine|hero|map_missing|npcs|startup/.test(String(busy.reason || '')) ? 2000 : 1200);
                return;
            }
            if (mode === 'exp') {
                const resumeTarget = sessionStorage.getItem('hero_resume_exp_target_map') || (typeof getExpResumeTargetMap === 'function' ? getExpResumeTargetMap('auto_resume') : null);
                if (typeof beginSafeExpResumeTravel === 'function') beginSafeExpResumeTravel(resumeTarget, 'auto_resume_after_reload');
                const btn = document.getElementById('btnStartExp');
                if (btn && !window.isExping) btn.click();
                if (window.logExp) window.logExp("Automatycznie wznowiono Expa po odswiezeniu gry.", "#4caf50");
            } else if (mode === 'patrol') {
                const btn = document.getElementById('btnStartStop');
                if (btn && typeof isPatrolling !== 'undefined' && !isPatrolling) btn.click();
                if (window.logHero) window.logHero("Automatycznie wznowiono Patrol po odswiezeniu gry.", "#4caf50");
            }
        };

        setTimeout(() => {
            if (sessionStorage.getItem('hero_resume_exp') === 'true') {
                resumeBotWhenStable('exp');
                return;
                let btn = document.getElementById('btnStartExp');
                if (btn && !window.isExping) btn.click();
                if (window.logExp) window.logExp("🔄 Automatycznie wznowiono Expa po odświeżeniu gry!", "#4caf50");
            } else if (sessionStorage.getItem('hero_resume_patrol') === 'true') {
                resumeBotWhenStable('patrol');
                return;
                let btn = document.getElementById('btnStartStop');
                if (btn && typeof isPatrolling !== 'undefined' && !isPatrolling) btn.click();
                if (window.logHero) window.logHero("🔄 Automatycznie wznowiono Patrol po odświeżeniu gry!", "#4caf50");
            }
        }, 1500); // 1.5 sekundy opóźnienia, żeby gra "odetchnęła" po wczytaniu

        console.log('[Boot] Inicjalizacja UI zakończona');
    }

   async function continueMargoneuroBootAfterReady(reason = 'boot_ready') {
        if (margoneuroInitialized) {
            return { ok: true, initialized: true, alreadyInitialized: true, reason };
        }
        const snapshot = getBootReadinessForLogger().snapshot;
        if (!isBootSnapshotReady(snapshot)) {
            return { ok: false, initialized: false, reason: 'not_ready', readiness: snapshot };
        }
        console.log('[Boot] Startuję weryfikację licencji');
        if (!(await margoneuroVerifyLicenseBeforeStart())) {
            return { ok: false, initialized: false, reason: 'license_failed', readiness: snapshot };
        }
        initializeMargoneuro();
        return { ok: true, initialized: true, reason, readiness: snapshot };
    }

   async function bootMargoneuroWhenGameReady() {
        if (margoneuroBootStarted) {
            console.log('[Boot] Boot już działa, pomijam drugi start');
            return;
        }

        margoneuroBootStarted = true;
        await waitForMargonemGameReady({ timeoutMs: 120000, intervalMs: 500, passiveIntervalMs: 2000 });
        await continueMargoneuroBootAfterReady('boot_loop');
        return;

        if (margoneuroInitialized) {
            return;
        }

        console.log('[Boot] Startuję weryfikację licencji');
        if (!(await margoneuroVerifyLicenseBeforeStart())) {
            return;
        }

        initializeMargoneuro();
    }

