                id: edgeId,
                fromMapKey,
                toMapKey,
                fromMapName: edge.fromMapName || edge.fromMap || out.maps[fromMapKey]?.mapName || out.nodes[fromMapKey]?.mapName || fromMapKey,
                toMapName: edge.toMapName || edge.toMap || out.maps[toMapKey]?.mapName || out.nodes[toMapKey]?.mapName || toMapKey,
