                toMapId: edge.toMapId ?? out.maps[toMapKey]?.mapId ?? out.nodes[toMapKey]?.mapId ?? null,
                groupKey: edge.groupKey || null,
                primaryTile: normalizeStaticTile(edge.primaryTile) || tiles[0] || null,
