        logEvent('STATIC-GRAPH', `persistence backend=${persistence.persistence || 'memory-only'}`, 3000, '#90caf9', { key: 'margoworld_static_persist_backend' });
        logEvent('STATIC-GRAPH', `canonical routing edges=${stats.canonicalRoutingEdges || stats.graphEdges}`, 3000, '#90caf9', { key: 'margoworld_static_canonical_edges' });
        logEvent('STATIC-GRAPH', `raw edges=${stats.rawGraphEdges || 0} groupedTransitions=${stats.groupedTransitions || 0}`, 3000, '#90caf9', { key: 'margoworld_static_raw_counts' });
        return { ok: true, loaded: true, persisted: !!persistence.persisted, persistence: persistence.persistence || 'memory-only', ...persistence, ...stats };
