    // ==========================================

    // SETUP & LOGIC

    // ==========================================

    function setMainGuiVisibility(visible) {
        const gui = document.getElementById('heroNavGUI');
        const gear = document.getElementById('gearIcon');
        if (!gui) return false;
        const shouldShow = visible !== false;
        gui.style.display = shouldShow ? 'flex' : 'none';
        if (gear) gear.style.display = shouldShow ? 'none' : 'flex';
        try { localStorage.setItem('margoneuro_main_visible_v1', shouldShow ? '1' : '0'); } catch (_) {}
        return true;
    }

    function installMainVisibilityToggle() {
        const toggleFn = function(forceVisible = null) {
            const gui = document.getElementById('heroNavGUI');
            const currentlyVisible = !!(gui && gui.style.display !== 'none');
            const nextVisible = typeof forceVisible === 'boolean' ? forceVisible : !currentlyVisible;
            return setMainGuiVisibility(nextVisible);
        };
        window.toggleMainVisibility = toggleFn;
        try { if (typeof unsafeWindow !== 'undefined' && unsafeWindow) unsafeWindow.toggleMainVisibility = toggleFn; } catch (_) {}
        try { if (typeof MARGONEURO_ROOT !== 'undefined' && MARGONEURO_ROOT) MARGONEURO_ROOT.toggleMainVisibility = toggleFn; } catch (_) {}
        return toggleFn;
    }
    installMainVisibilityToggle();

    function handleGlobalKeydown(e) {
        const tag = String(e?.target?.tagName || '').toUpperCase();
        if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
        if (e.code === 'Escape' || e.key === 'Escape') {
            const gui = document.getElementById('heroNavGUI');
            if (gui && gui.style.display !== 'none' && typeof window.toggleMainVisibility === 'function') {
                window.toggleMainVisibility(false);
                e.preventDefault();
                e.stopPropagation();
                return;
            }
        }
        if (botSettings.toggleKey && e.code === botSettings.toggleKey && typeof window.toggleMainVisibility === 'function') {
            window.toggleMainVisibility();
        }
    }

// --- MODUŁ: POWIADOMIENIA PRZEGLĄDARKI ---
