            const direct = list?.[id] || list?.[String(id)];
            if (direct) return { id, npc: direct, data: direct.d || direct };
            for (const key in (list || {})) {
                const npc = list[key];
                const data = npc?.d || npc || {};
                if (String(data.id ?? key) === String(id)) return { id, npc, data };
            }
            return null;
