    const levels = history.map(m => Number(m?.lvl || m?.level || 0)).filter(lvl => Number.isFinite(lvl) && lvl > 0);
    const memoryMax = Number(window.mapMonsterMemory?.[mapState?.normalizedKey]?.maxMonsterLevel || 0);
    if (memoryMax > 0) levels.push(memoryMax);
    const staticInfo = getStaticExpLevelInfoForMap(mapState?.mapName || mapState?.normalizedKey || '');
    if (staticInfo?.mobLevelMax > 0) levels.push(staticInfo.mobLevelMax);
