    const fallbackMs = Math.max(4 * 60 * 1000, Math.min(8 * 60 * 1000, RESPAWN_FALLBACK_CLEAN_TTL_MS || 5 * 60 * 1000));
    let baseRespawnMs = Number(estimate?.estimatedRespawnMs || 0);
    if (!Number.isFinite(baseRespawnMs) || baseRespawnMs < 60000) baseRespawnMs = fallbackMs;
    const cooldownMs = Math.max(60000, Math.min(RESPAWN_MAX_CLEAN_TTL_MS, addRespawnJitter(baseRespawnMs, 0.12)));
