        reason,
        ts: Number(meta.ts || now),
        cleanedAt: Number(meta.cleanedAt || state?.lastClearedAt || now),
        cleanUntil,
        nextCheckAt: cleanUntil,
        cooldownMs: Math.max(0, cleanUntil - now),
