    const waitMs = isRedMap ? 650 : EXP_MIN_CLEAR_CONFIRM_AFTER_LAST_KILL_MS;
    const maxWaitMs = isRedMap ? EXP_RED_EMPTY_FORCE_CLEAR_AFTER_MS : EXP_MAX_CLEAR_CONFIRM_NORMAL_MS;
    const minRescans = isRedMap ? (noFocusTarget ? EXP_RED_EMPTY_MIN_RESCANS : Math.min(EXP_EMPTY_REQUIRED_SCANS_RED, 3)) : EXP_EMPTY_REQUIRED_SCANS_NORMAL;
