    const filteredMobs = validMobs.filter(m => !isTargetIgnoredOnMap(mapName, m));
    if (!filteredMobs.length) return null;
    const lock = typeof getExpTargetLock === 'function' ? getExpTargetLock() : null;
    const lockedMob = typeof getLockedExpTargetCandidate === 'function' ? getLockedExpTargetCandidate(filteredMobs, lock) : null;
