        getClearedExpMaps: () => (typeof getClearedExpMaps === 'function' ? JSON.parse(JSON.stringify(getClearedExpMaps())) : {}),
        clearExpClearedMaps: () => (typeof clearExpClearedMaps === 'function' ? clearExpClearedMaps() : false),
        getExpRotationSnapshot: () => (typeof getExpRotationSnapshot === 'function' ? getExpRotationSnapshot() : null),
