        debugExpireMapCooldown: (mapNameOrKey) => (typeof debugExpireMapCooldown === 'function' ? debugExpireMapCooldown(mapNameOrKey) : { ok: false, reason: 'missing_helper' }),
        forceContinueExpFromCleanMap: () => (typeof continueExpFromCleanMap === 'function' ? continueExpFromCleanMap() : { ok: false, reason: 'missing_helper' }),
        getMobFilterReport: () => (typeof getMobFilterReport === 'function' ? getMobFilterReport() : null),
        debugClassifyVisibleMobs: () => (typeof debugClassifyVisibleMobs === 'function' ? debugClassifyVisibleMobs() : []),
